import {goldenGuideGeometry,DEFAULTS,PROJECTION} from '../geometry.mjs';
const directions=[{id:'signal',name:'Signal Blue',mood:'Precise / trusted',note:'The closest continuation of the supplied blue mark. Restrained product surfaces, clear hierarchy and one confident accent.',colors:['#0D1423','#F4F7FF','#79AAFF','#3678EE','#ACB6CA'],font:'Inter'},{id:'violet',name:'Ultraviolet',mood:'Expressive / intelligent',note:'A more expressive direction: violet fields, geometric typography and a spacious, editorial voice.',colors:['#181022','#FBF6FF','#C2A4FF','#7147EB','#B9AACB'],font:'Space Grotesk'},{id:'carbon',name:'Carbon',mood:'Quiet / architectural',note:'A monochrome identity that lets form do the work. Useful when Vortex should feel like a calm, durable layer of infrastructure.',colors:['#EEEEEB','#161719','#161719','#D8DAD6','#676965'],font:'Inter'},{id:'ion',name:'Ion',mood:'Fast / technical',note:'A sharper, developer-facing direction. Acid yellow, near-black and compact technical labels give the system more energy.',colors:['#161A11','#F3F7E9','#D3F879','#B8DE56','#A9B593'],font:'Space Grotesk'}];
let active='signal';
const $=s=>document.querySelector(s);
$('#direction-grid').innerHTML=directions.map((d,i)=>`<button class="direction-card" data-direction="${d.id}" aria-pressed="${i===0}" aria-label="Apply ${d.name} direction"><div class="direction-art theme-surface" data-palette="${d.id}"><span class="mono">0${i+1} / ${d.mood.toUpperCase()}</span><i class="mark" aria-hidden="true"></i><span class="word">${d.id==='ion'?'VORTEX_':'Vortex'}</span></div><div class="direction-caption"><span>${d.name}</span><small>0${i+1}</small></div></button>`).join('');
function setDirection(id){active=id;const i=directions.findIndex(d=>d.id===id),d=directions[i];document.querySelectorAll('[data-direction]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.direction===id)));document.querySelectorAll('.theme-surface:not(.direction-art)').forEach(e=>e.dataset.palette=id);$('#active-direction').textContent=`0${i+1} / ${d.name.toUpperCase()}`;$('#direction-note').textContent=d.note;if($('#palette'))renderPalette(d);document.querySelectorAll('[data-active-name]').forEach(e=>e.textContent=d.name);if($('#type-name'))$('#type-name').textContent=d.font;updateDownloadLinks();}
const mark='<i class="mark" aria-hidden="true"></i>';
const lockup=`<span class="lockup">${mark}<span>Vortex</span></span>`;
const heading=(n,label,title,description)=>`<div class="section-heading"><div><span class="mono">${n} / ${label}</span><h2>${title}</h2></div><p>${description}</p></div>`;
const specimen=(n,title,cls,body,wide=false)=>`<figure class="specimen ${wide?'wide':''}"><div class="specimen-art theme-surface ${cls}" data-palette="signal">${body}</div><figcaption><span><b>${n}</b> ${title}</span><span data-active-name>Signal Blue</span></figcaption></figure>`;
$('#guide-sections').innerHTML=`
<section id="logo">${heading('03','THE IDENTITY','One idea. Two expressions.','Both supplied SVGs, presented without changing their paths. Switch the mark to compare it throughout the page.')}
<div class="logo-options">${[1,2].map(n=>`<button class="logo-option" data-variation="${n}" aria-pressed="${n===1}" aria-label="Use logo variation ${n}"><div class="logo-stage dot-grid"><i class="mark" style="--logo:url('../assets/brand/vortex-${n}.svg')" aria-hidden="true"></i><span class="axis horizontal"></span><span class="axis vertical"></span></div><span class="logo-option-caption"><span>Variation 0${n}</span><small>${n===1?'Open, expansive silhouette':'Compact, sharper silhouette'}</small></span></button>`).join('')}</div>
<div class="lockup-grid"><article class="lockup-sample theme-surface"><span class="mini-label mono">PRIMARY / HORIZONTAL</span>${lockup}<span class="sample-caption">Everyday identity</span></article><article class="lockup-sample stacked theme-surface"><span class="mini-label mono">SECONDARY / STACKED</span><div>${mark}<strong>Vortex</strong><span>AI Company brain</span></div><span class="sample-caption">Introductions & covers</span></article><article class="lockup-sample wordmark-only theme-surface"><span class="mini-label mono">COMPACT / WORDMARK</span><strong>Vortex<span class="wordmark-period">.</span></strong><span class="sample-caption">When the symbol is nearby</span></article></div>
<p class="fine-print">Use “Vortex” in title case. “VORTEX_” is an optional campaign treatment in the Ion direction. Keep the descriptor as “AI Company brain”; omit it when it would be smaller than 14 px.</p>
</section>
<section id="construction">${heading('04','GEOMETRY & RESTRAINT','Built from a continuous idea.','The first supplied mark uses five rotated golden spirals. Construction lines explain the form; they are not part of the everyday logo.')}
<div class="construction-grid"><figure class="technical-board"><div class="board-heading"><span class="mono">VARIATION 01 / SPIRAL STUDY</span><button id="construction-toggle" aria-pressed="true" class="small-button">Hide guides</button></div><svg id="construction-svg" viewBox="-410 -270 820 540" role="img" aria-label="Five-arm original logo with a golden spiral centerline and phi-scaled radii"></svg><figcaption><span>φ ≈ 1.618</span><span>5 arms · 72° rotation · 30° projection</span></figcaption></figure><div class="construction-notes"><div><span class="formula">r(θ + 90°) = φ · r(θ)</span><h3>Growth, then rotation.</h3><p>Radius grows by φ each quarter-turn in the original plane. Five copies sit 72° apart before the vertical isometric compression. The overlaid line follows arm 1.</p></div><div><span class="formula">x = W / 8</span><h3>Space is part of the mark.</h3><p>Use one x of clear space around the visible silhouette. Measure W across the ink, not the SVG canvas. For a wordmark lockup, keep one x around the full group.</p></div><a href="https://mathworld.wolfram.com/GoldenSpiral.html" target="_blank" rel="noreferrer" class="source-link">Golden spiral reference · Wolfram MathWorld ↗</a></div></div>
<div class="two-column"><figure class="clearspace technical-board"><div class="board-heading"><span class="mono">CLEAR SPACE / PROPOSED RULE</span><span class="mono">1x MINIMUM</span></div><div class="clearspace-stage"><div class="clear-outer"><div class="clear-inner"><i class="mark fixed-v1" aria-hidden="true"></i></div><span class="measure measure-top">← W →</span><span class="measure measure-side">x</span><span class="corner-label">x = W / 8</span></div></div><figcaption>Use 2x at page edges when space allows.</figcaption></figure><article class="size-board technical-board"><div class="board-heading"><span class="mono">SCREEN SIZE / ACTUAL PIXELS</span></div><div class="size-samples">${[24,32,48,64,96].map(n=>`<div><i class="mark fixed-v1" style="width:${n}px" aria-hidden="true"></i><span>${n}px</span></div>`).join('')}</div><p><b>48 px mark width</b> is the proposed starting minimum. At 24–32 px, the dense center loses detail. Use the wordmark or commission a separate small-size mark for those placements.</p><p class="fine-print">For print, begin at 12 mm wide and proof on the actual stock. These are design recommendations, not tested production limits.</p></article></div>
<div class="usage-grid">${[{cls:'correct',label:'Keep the original proportions',note:'Scale uniformly. Use a single solid color.'},{cls:'distort',label:'Do not stretch',note:'The isometric projection is already built in.'},{cls:'rotate',label:'Do not rotate casually',note:'Preserve the supplied orientation.'},{cls:'effect',label:'Do not add effects',note:'Avoid glow, outlines and drop shadows in the core identity.'}].map((x,i)=>`<article class="usage ${x.cls}"><div>${mark}</div><h3><span>${i===0?'✓':'×'}</span> ${x.label}</h3><p>${x.note}</p></article>`).join('')}</div>
</section>
<section id="color">${heading('05','A CONTROLLED PALETTE','Color with a job to do.','Each direction has a surface, a text color, a readable accent, a stronger field color and secondary text. Click a swatch to copy its hex value.')}
<div class="palette-head"><span class="mono" data-active-name>Signal Blue</span><a href="#directions" class="small-link">Change direction ↑</a></div><div id="palette" class="palette"></div><div class="color-bottom"><div><h3>Start with 80 / 15 / 5.</h3><p>About 80% neutral surface, 15% type and structural elements, 5% accent. Use a full accent field for a campaign moment; keep the product quieter.</p><div class="proportion-bar theme-surface"><span></span><span></span><span></span></div></div><div><h3>Readable combinations.</h3><div id="contrast-pairs"></div><p class="fine-print">Ratios shown for these exact pairs. Target ≥ 4.5:1 for normal text. Field colors are not automatically text-safe. <a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html" target="_blank" rel="noreferrer">WCAG contrast guidance ↗</a></p></div></div>
</section>
<section id="type">${heading('06','VOICE IN TYPE','Clear thought. Clear typography.','Inter keeps the system precise and familiar. Space Grotesk adds character to expressive directions. Use a system monospace only for metadata, measurements and code.')}
<div class="type-feature theme-surface"><div><span class="mono">SELECTED / <span id="type-name">Inter</span></span><div class="type-abc">Aa</div><span class="type-glyphs">0123456789 &amp; @ → φ</span></div><div class="type-quote">Everything your<br>company knows.<br><span>Working together.</span></div></div>
<div class="two-column"><article class="font-sample inter"><span class="mono">INTER / SIGNAL & CARBON</span><h3>Make context<br>second nature.</h3><p>Neutral, direct and quiet. Use 500 for headlines, 400 for body and 600 for emphasis.</p></article><article class="font-sample space"><span class="mono">SPACE GROTESK / VIOLET & ION</span><h3>Intelligence<br>in every direction.</h3><p>Geometric forms add a more distinctive voice. Keep body copy in Inter for continuity.</p></article></div>
<div class="type-scale"><div><span class="mono">DISPLAY / 64 · 1.05 · −0.05em</span><span class="scale-display">Connected.</span></div><div><span class="mono">HEADING / 40 · 1.15 · −0.03em</span><span class="scale-heading">A shared understanding.</span></div><div><span class="mono">BODY / 16 · 1.6 · 0</span><span class="scale-body">Turn scattered knowledge into useful context.</span></div><div><span class="mono">LABEL / 12 · 1.5 · +0.06em</span><span class="mono">CONTEXT / SOURCES / ACTION</span></div></div>
<div class="voice-row"><div><span class="mono">SAY</span><p>“Find the decision.<br>Understand the reason.”</p></div><div><span class="mono">AVOID</span><p>“Unleash revolutionary,<br>next-generation AI synergy.”</p></div><div><h3>A useful voice.</h3><p>Lead with the job. Be specific about sources. Show uncertainty plainly. Make the next step easy to understand.</p></div></div>
</section>
<section id="layout">${heading('07','COMPOSITION & RHYTHM','Let the proportions do the work.','Use the φ grid to place focal points, then a simple spacing system to make the layout practical. A compositional aid, not a rule for every screen.')}
<div class="grid-controls"><span class="mono">PHI GRID / .382 + .618</span><button class="small-button" id="phi-toggle" aria-pressed="true">Hide φ grid</button></div><div class="phi-demo theme-surface"><div class="phi-overlay"><span class="phi-line v a"></span><span class="phi-line v b"></span><span class="phi-line h a"></span><span class="phi-line h b"></span><span class="phi-dot aa"></span><span class="phi-dot ab"></span><span class="phi-dot ba"></span><span class="phi-dot bb"></span><span class="phi-label l-a">.382</span><span class="phi-label l-b">.618</span></div><span class="phi-brand">Vortex</span><div class="phi-message">A company.<br>A shared mind.</div><i class="mark phi-logo" aria-hidden="true"></i><span class="phi-descriptor">AI Company brain</span><span class="phi-foot mono">INTELLIGENCE, IN CONTEXT.</span></div>
<div class="layout-explainer"><div><h3>Anchor what matters.</h3><p>The headline block’s upper-right corner is anchored at x = 38.2%, y = 38.2%. The logo’s center sits at x = 61.8%, y = 61.8%. Keep important elements near an intersection; avoid stacking everything on it.</p></div><div><h3>Optical balance wins.</h3><p>The grid divides a frame into 38.2 / 23.6 / 38.2%. It does not make the frame itself a golden rectangle. Adjust placement for the actual content, and simplify on mobile.</p></div><details><summary>View supplied φ-grid reference</summary><img src="../assets/brand/phi-grid.png" alt="Original reference showing a phi grid with focal points at 38.2 and 61.8 percent" width="666" height="532" loading="lazy"></details></div>
<div class="two-column"><article class="spacing-board technical-board"><span class="mono">SPACING / 4 PX BASE</span><div class="spacing-bars">${[4,8,12,16,24,32,48,64].map(x=>`<div><span>${x}</span><i style="width:${x*3}px"></i></div>`).join('')}</div><p>Use 8–12 px within a group, 24–32 px between groups and 48–64 px between sections. Use φ for composition, not fractional padding.</p></article><article class="grid-board technical-board"><span class="mono">DOT GRID / 24 PX PITCH</span><div class="dot-specimen">${mark}<span class="dot-distance mono">← 24 →</span></div><p>1 px dots at roughly 10–15% opacity. Keep the pattern off body copy and dense UI. Registration crosses belong at the frame corners.</p></article></div>
</section>
<section id="specimens">${heading('08','APPLICATION STUDIES','A system, beyond the symbol.','Twelve specimens show the selected direction in different settings. These scaled compositions explore the identity; product screens are illustrative.')}<div class="specimen-toolbar"><span><b data-active-name>Signal Blue</b><span id="active-variation"> / Variation 01</span></span><a href="#directions">Change direction ↑</a></div>
<div class="specimen-grid">
${specimen('01','Product workspace','product-specimen',`<div class="product-top">${lockup}<span class="mono">WORKSPACE / STUDIO</span></div><div class="product-layout"><div class="product-nav"><b>Company brain</b><span>Overview</span><span class="selected">Ask Vortex</span><span>Sources</span><span>Decisions</span><span>Collections</span><small>CONNECTED KNOWLEDGE</small><span>Design notes</span><span>Product updates</span></div><div class="product-content"><span class="mono">GOOD MORNING</span><h3>What do you<br>want to understand?</h3><div class="ask-box">What changed in the launch plan? <span>↵</span></div><div class="answer-preview"><span class="mono">CONTEXT, CONNECTED</span><p>The design review moved the launch to Thursday so the team can finish accessibility checks.</p><div><span>Design review ↗</span><span>Launch notes ↗</span></div></div></div></div>`,true)}
${specimen('02','Command surface','command-specimen',`<div class="command-window"><div class="command-input">${mark}<span>Find the reason behind a decision</span><kbd>⌘ K</kbd></div><div class="command-result"><span class="result-icon">↳</span><div><b>Why did the launch move?</b><span>Decision · Product & design</span></div><span>↵</span></div><div class="command-result"><span class="result-icon">⌕</span><div><b>Search company knowledge</b><span>Documents, conversations, decisions</span></div></div><div class="command-hint mono">↑ ↓ TO NAVIGATE <span>↵ TO OPEN</span></div></div>`)}
${specimen('03','App icon family','icon-specimen',`<div class="icon-row"><div class="app-icon">${mark}</div><div class="app-icon light-icon">${mark}</div><div class="app-icon accent-icon">${mark}</div></div><span class="mono">SOLID / REVERSED / ACCENT</span><p>One mark. Enough room to breathe.</p>`)}
${specimen('04','Launch announcement','launch-specimen',`<span class="mono">INTRODUCING VORTEX</span><h3>Your company.<br>Finally connected.</h3>${mark}<div class="specimen-bottom"><span>AI Company brain</span><span>Vortex / 01</span></div>`,true)}
${specimen('05','Presentation cover','slide-specimen',`<span class="mono">VORTEX / PRODUCT VISION</span><div class="slide-body"><span class="slide-number">01</span><h3>From information<br>to understanding.</h3></div><div class="specimen-bottom">${lockup}<span class="mono">COMPANY INTELLIGENCE</span></div>`)}
${specimen('06','Square campaign','square-specimen',`<span class="mono">CONTEXT IS EVERYTHING.</span><i class="mark campaign-mark" aria-hidden="true"></i><h3>Less searching.<br>More knowing.</h3><div class="specimen-bottom"><span>Vortex</span><span>AI Company brain</span></div>`)}
${specimen('07','Business cards','cards-specimen',`<div class="business-card card-back">${mark}<span>AI Company brain</span></div><div class="business-card card-front">${lockup}<div><b>Alex Morgan</b><span>Product & engineering</span></div><span class="mono">VORTEX / PEOPLE & CONTEXT</span></div>`)}
${specimen('08','Document cover','document-specimen',`<div class="document-sheet"><span class="document-top">VORTEX <span>FIELD NOTES / 01</span></span><h3>The<br>connected<br>company.</h3><p>A practical guide to<br>shared understanding.</p>${mark}<div class="document-foot"><span>AI Company brain</span><span>01 — 12</span></div></div>`)}
${specimen('09','Developer identity','terminal-specimen',`<div class="terminal-top"><span>vortex / context</span><span>⌘</span></div><div class="terminal-body"><span class="terminal-logo">VORTEX_</span><p><span class="terminal-accent">›</span> context: ready<br><span class="terminal-accent">›</span> sources: connected<br><span class="terminal-accent">›</span> decisions: traceable</p><div class="terminal-prompt">$ ask "what changed?"<span class="cursor"></span></div></div><span class="terminal-caption mono">ILLUSTRATIVE DEVELOPER EXPRESSION</span>`)}
${specimen('10','Monochrome print','print-specimen',`<div class="print-head"><span class="mono">VORTEX / RESEARCH NOTES</span><span>2026</span></div><h3>Knowledge<br>has a shape.</h3>${mark}<div class="specimen-bottom"><span>AI Company brain</span><span class="mono">ONE-COLOR STUDY</span></div>`)}
${specimen('11','Email signature','email-specimen',`<div class="email-paper"><p>Thanks,<br>Alex</p><div class="email-signature">${mark}<div><b>Alex Morgan</b><span>Product & engineering</span><strong>Vortex <span>AI Company brain</span></strong></div></div><span class="signature-note">Plain text first. One restrained brand cue.</span></div>`)}
${specimen('12','Motion study','motion-specimen',`<div class="motion-orbit">${mark}</div><div class="motion-controls"><span class="mono">ASSEMBLE / SETTLE / HOLD</span><button id="replay-motion" class="small-button">Replay ↻</button></div><p>Reveal once, then stay still. 600 ms, ease-out. Reduced-motion preferences are respected.</p>`)}
</div></section>
<section id="downloads">${heading('09','TAKE IT FURTHER','A useful starting kit.','Download the supplied originals, a solid-color treatment of your selected mark, or the palette. All spacing and usage rules here are proposals to refine as the identity develops.')}
<div class="download-grid"><a href="../assets/brand/vortex-brand-kit.zip" download><span class="download-icon">↧</span><div><h3>Brand exploration kit</h3><p>Originals, monochrome SVGs, four palettes & usage notes.</p></div><span>ZIP</span></a><a id="download-logo" href="../assets/brand/vortex-signal-1.svg" download><span class="download-icon">↧</span><div><h3>Selected logo</h3><p>Current variation in the selected accent color.</p></div><span>SVG</span></a><a id="download-palette" href="../assets/brand/palette-signal.json" download><span class="download-icon">↧</span><div><h3>Selected palette</h3><p>Named colors and typography choices.</p></div><span>JSON</span></a></div>
<div class="asset-links"><a href="../assets/brand/vortex-1-original.svg" download>Original variation 01 ↧</a><a href="../assets/brand/vortex-2-original.svg" download>Original variation 02 ↧</a><a href="../">Open geometry studio ↗</a></div><p class="fine-print">The originals retain their supplied color and opacity. Brand treatments use solid fills while preserving every path. Fonts: Inter and Space Grotesk, distributed under the SIL Open Font License. <a href="../assets/brand/inter-OFL.txt">Inter license</a> · <a href="../assets/brand/spacegrotesk-OFL.txt">Space Grotesk license</a>.</p>
</section>`;

const guide=goldenGuideGeometry({...DEFAULTS,model:'golden',armCount:5,endpoint:90,innerWidth:20,outerWidth:47.5,taper:'radial'});
$('#construction-svg').innerHTML=`<defs><pattern id="construction-dots" width="22" height="22" patternUnits="userSpaceOnUse"><circle cx="0" cy="0" r=".9" fill="#6582a4" opacity=".3"/></pattern></defs><rect x="-410" y="-270" width="820" height="540" fill="url(#construction-dots)"/><image href="../assets/brand/vortex-1-original.svg" x="-326.75" y="-188.649" width="653.5" height="377.298" opacity=".65"/><g id="construction-lines"><path d="M-370,0H370M0,-230V230" fill="none" stroke="#6d8dad" stroke-width=".8" stroke-dasharray="4 5"/>${guide.checkpoints.map((p,i)=>`<ellipse cx="0" cy="0" rx="${p.radius}" ry="${p.radius*PROJECTION}" fill="none" stroke="#d6bd82" stroke-width=".9" opacity=".6"/><circle cx="${p.point[0]}" cy="${p.point[1]}" r="4" fill="#edce83"/><text x="${p.point[0]+12}" y="${p.point[1]+(i===0?20:-10)}" fill="#f1d393" font-size="16" paint-order="stroke" stroke="#101722" stroke-width="4">${['R','R / φ','R / φ²','R / φ³'][i]}</text>`).join('')}<path d="${guide.center}" stroke="#0b0c0f" stroke-width="4" fill="none"/><path d="${guide.center}" stroke="#ffd68b" stroke-width="1.8" fill="none" stroke-dasharray="5 4"/></g>`;
const roles=['Surface','Primary text','Accent','Field','Secondary text'];
function luminance(hex){const c=hex.match(/[a-f\d]{2}/gi).map(v=>parseInt(v,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return c[0]*.2126+c[1]*.7152+c[2]*.0722;}
function contrast(a,b){const x=luminance(a),y=luminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
function renderPalette(d){$('#palette').innerHTML=d.colors.map((c,i)=>`<button class="swatch" data-copy="${c}" aria-label="Copy ${roles[i]} ${c}"><span class="swatch-color" style="background:${c};color:${luminance(c)>.4?'#161719':'#f4f7ff'}"><span>0${i+1}</span><span>↗</span></span><span class="swatch-meta"><b>${roles[i]}</b><code>${c}</code></span></button>`).join('');$('#contrast-pairs').innerHTML=[[1,0,'Primary / surface'],[2,0,'Accent / surface'],[4,0,'Secondary / surface']].map(([a,b,label])=>{const ratio=contrast(d.colors[a],d.colors[b]);return `<div class="contrast-row"><span style="color:${d.colors[a]};background:${d.colors[b]}">Aa</span><span>${label}</span><b>${ratio.toFixed(2)}:1</b><small>${ratio>=4.5?'AA text':'Large text only'}</small></div>`;}).join('');}
let variation=1,noticeTimeout;
function notify(message){$('#notice').textContent=message;$('#notice').classList.add('visible');clearTimeout(noticeTimeout);noticeTimeout=setTimeout(()=>$('#notice').classList.remove('visible'),2500);}
document.querySelectorAll('[data-direction]').forEach(b=>b.addEventListener('click',()=>{setDirection(b.dataset.direction);notify(`${directions.find(d=>d.id===active).name} applied to all specimens`);}));
document.querySelectorAll('[data-variation]').forEach(b=>b.addEventListener('click',()=>{variation=+b.dataset.variation;document.documentElement.style.setProperty('--logo',`url('../assets/brand/vortex-${variation}.svg')`);document.querySelectorAll('[data-variation]').forEach(el=>el.setAttribute('aria-pressed',String(+el.dataset.variation===variation)));$('#active-variation').textContent=` / Variation 0${variation}`;updateDownloadLinks();notify(`Variation 0${variation} applied. Construction diagram remains variation 01.`);}));
$('#palette').addEventListener('click',async e=>{const b=e.target.closest('[data-copy]');if(!b)return;try{await navigator.clipboard.writeText(b.dataset.copy);notify(`${b.dataset.copy} copied`);}catch{notify(`Color: ${b.dataset.copy} — select the hex text to copy.`);}});
$('#construction-toggle').addEventListener('click',e=>{const on=e.currentTarget.getAttribute('aria-pressed')!=='true';e.currentTarget.setAttribute('aria-pressed',String(on));e.currentTarget.textContent=on?'Hide guides':'Show guides';$('#construction-lines').style.display=on?'':'none';});
$('#phi-toggle').addEventListener('click',e=>{const on=e.currentTarget.getAttribute('aria-pressed')!=='true';e.currentTarget.setAttribute('aria-pressed',String(on));e.currentTarget.textContent=on?'Hide φ grid':'Show φ grid';$('.phi-overlay').hidden=!on;});
$('#replay-motion').addEventListener('click',()=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches){notify('Reduced motion is enabled. The mark stays still.');return;}$('.motion-orbit .mark').animate([{opacity:0,transform:'translateY(12px) scale(.9)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:600,easing:'cubic-bezier(.16,1,.3,1)'});});
function updateDownloadLinks(){if(!$('#download-logo'))return;$('#download-logo').href=`../assets/brand/vortex-${active}-${variation}.svg`;$('#download-palette').href=`../assets/brand/palette-${active}.json`;}
const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){document.querySelectorAll('.rail nav a').forEach(a=>{if(a.getAttribute('href')==='#'+e.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}},{rootMargin:'-5% 0px -65% 0px',threshold:0});document.querySelectorAll('main section').forEach(s=>observer.observe(s));
setDirection(active);
